def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter

    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    colors = [v for v in counts if v != bg]
    if len(colors) < 2:
        return [row[:] for row in grid]

    # The most frequent non-background color is the scattered marker;
    # the remaining colors form the stamp.
    marker = max(colors, key=lambda v: counts[v])
    stamp_colors = set(colors) - {marker}

    # Find a horizontal or vertical seed line containing stamp colors,
    # allowing background-colored cells within the line.
    seed = None
    for r in range(h):
        positions = [c for c in range(w) if grid[r][c] in stamp_colors]
        if positions:
            lo, hi = min(positions), max(positions)
            if all(grid[r][c] != marker for c in range(lo, hi + 1)):
                seed = (0, r, lo, hi)
                break
    if seed is None:
        for c in range(w):
            positions = [r for r in range(h) if grid[r][c] in stamp_colors]
            if positions:
                lo, hi = min(positions), max(positions)
                if all(grid[r][c] != marker for r in range(lo, hi + 1)):
                    seed = (1, c, lo, hi)
                    break
    if seed is None:
        return [row[:] for row in grid]

    axis, fixed, lo, hi = seed
    # Include any background padding in the seed's span (e.g. 0 0 1 0 0).
    pattern = [grid[fixed][i] for i in range(lo, hi + 1)] if axis == 0 else [
        grid[i][fixed] for i in range(lo, hi + 1)
    ]
    center = (len(pattern) - 1) // 2
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == marker:
                for i, value in enumerate(pattern):
                    rr, cc = (r, c + i - center) if axis == 0 else (r + i - center, c)
                    if 0 <= rr < h and 0 <= cc < w:
                        out[rr][cc] = value
    return out
